with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, 'フォリー＝ベルジェールのバー', 'エドゥアール・マネ', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/Un_bar_aux_Folies-Berg%C3%A8re_d%27E._Manet_%28Fondation_Vuitton%2C_Paris%29_%2833539037428%29.jpg/960px-Un_bar_aux_Folies-Berg%C3%A8re_d%27E._Manet_%28Fondation_Vuitton%2C_Paris%29_%2833539037428%29.jpg', 'パリのミュージックホール「フォリー＝ベルジェール」のカウンターに立つ女性給仕を描いた、マネ最後の大作です。1882年のサロンに出品され、現在はロンドンのコートールド・ギャラリーが所蔵しています。背後の大きな鏡には、にぎわう客席や、左上の空中ブランコの曲芸師の足まで映り込んでいます。ところが鏡に映る女性の後ろ姿は右へずれていて、正面の姿との食い違いが見る人を戸惑わせます。華やかな都市の娯楽と、その中心でどこか虚ろな表情を見せる女性との対比が見どころです。', 'CC BY 2.0', 'Édouard Manet', 'https://commons.wikimedia.org/wiki/File:Un_bar_aux_Folies-Bergère_d''E._Manet_(Fondation_Vuitton,_Paris)_(33539037428).jpg'),
    (2, '松島図屏風', '俵屋宗達', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/%E4%BF%B5%E5%B1%8B%E5%AE%97%E9%81%94%E3%80%8A%E6%9D%BE%E5%B3%B6%E5%9B%B3%E3%80%8B17%E4%B8%96%E7%B4%80%E3%80%81%E3%83%95%E3%83%AA%E3%83%BC%E3%82%A2%E7%BE%8E%E8%A1%93%E9%A4%A82.jpg/960px-%E4%BF%B5%E5%B1%8B%E5%AE%97%E9%81%94%E3%80%8A%E6%9D%BE%E5%B3%B6%E5%9B%B3%E3%80%8B17%E4%B8%96%E7%B4%80%E3%80%81%E3%83%95%E3%83%AA%E3%83%BC%E3%82%A2%E7%BE%8E%E8%A1%93%E9%A4%A82.jpg', '金地の画面いっぱいに、うねる波と岩、松の生えた小島を描いた六曲一双の屏風です。江戸時代初期の17世紀に俵屋宗達が描いたもので、現在はアメリカ・ワシントンのフリーア美術館が所蔵しています。題名は宮城の松島にちなみますが、実際の景色を写したものではなく、何重にも重ねた波の線や、金色の雲・砂洲を大胆な形に置き換えて画面を構成しています。装飾性と力強い動きをあわせもつこの表現は、のちの尾形光琳ら琳派の画家たちにも受け継がれました。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:俵屋宗達《松島図》17世紀、フリーア美術館2.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

