    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('カジミール・マレーヴィチ', 'Kazimir Malevich', 'マレーヴィチ',
        1879, 1935, 'west', array['cubism', 'futurism']::text[],
        '「黒の正方形」でシュプレマティスムを唱え、抽象絵画の転換点をつくった画家。', '1879年、ロシア帝国のキーウ（キエフ）に生まれ、モスクワで絵画を学びました。初めは印象派や象徴主義の影響を受け、やがてフランスのキュビスムとイタリアの未来派を取り入れた「立体未来派」の作品を描きます。

1915年、ペトログラードの「0,10」展で、白い地に黒い正方形だけを描いた「黒の正方形」などを発表し、形や色そのものがもたらす感覚を重んじるシュプレマティスムを唱えました。描く対象を完全に捨てたこの試みは、抽象絵画の大きな転換点となりました。

ロシア革命の後は美術教育にも携わりましたが、晩年には再び人物などを描いた作品も残しています。1935年にレニングラードで亡くなり、その考え方は構成主義やのちの抽象美術に影響を与えました。', 'https://ja.wikipedia.org/wiki/%E3%82%AB%E3%82%B8%E3%83%9F%E3%83%BC%E3%83%AB%E3%83%BB%E3%83%9E%E3%83%AC%E3%83%BC%E3%83%B4%E3%82%A3%E3%83%81')
